module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    // The concatenated output matches 4-bit addition with carry-in.
    check_total_addition: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Sum bit 0 is the XOR of the LSB inputs and carry-in.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Sum bit 1 uses the carry generated by bit 0.
    check_bit1_sum_from_carry0: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))))
    );

    // Sum bit 2 uses the carry generated by bit 1.
    check_bit2_sum_from_carry1: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) &
                   (A[1] ^ B[1]))))
    );

    // Sum bit 3 uses the carry generated by bit 2.
    check_bit3_sum_from_carry2: assert property (
        @(posedge clk)
        S[3] == (A[3] ^ B[3] ^
                 ((A[2] & B[2]) |
                  (((A[1] & B[1]) |
                    (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) &
                     (A[1] ^ B[1]))) &
                   (A[2] ^ B[2]))))
    );

    // Carry-out is the final carry from the ripple-carry chain.
    check_final_carry: assert property (
        @(posedge clk)
        Cout == ((A[3] & B[3]) |
                 (((A[2] & B[2]) |
                   (((A[1] & B[1]) |
                     (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) &
                      (A[1] ^ B[1]))) &
                    (A[2] ^ B[2]))) &
                  (A[3] ^ B[3])))
    );

endmodule